    doc.addFileToVFS('Poppins-700.ttf', ASSET.f700); doc.addFont('Poppins-700.ttf', 'Poppins', 'bold');
    const PW = 612, PH = 792, M = 40, CW = PW - 2 * M, BOT = PH - 56; let y = 0, page = 1;
    const x = B.med.read(r), sum = L.summarize(r.values), w = who(r), lab = labOf(r), code = L.docCode(r.id, r.date);
