      const hs = rows.map(function (row) { let m = 1; row.forEach(function (it) { m = Math.max(m, lines(it[1], cw - 8, 'bold', 10).length); }); return 13 + m * 13 + 8; });
      const total = hs.reduce(function (a, b) { return a + b; }, 0) + 12; ensure(total); card(total);
