      ensure(h); fill(lv[1]); doc.roundedRect(M, y, CW, h, 6, 6, 'F'); fill(lv[0]); doc.rect(M, y + 6, 4, h - 12, 'F');
      font('bold', 8); ink(lv[0]); doc.text(T(lv[2].toUpperCase()), M + 18, y + 20);
