      if (r.pos) Object.keys(r.pos).forEach(function (k) { const p = r.pos[k]; extra.push((D.BY_ID[k] ? D.BY_ID[k].name : k) + ': ' + p.res + (p.detail ? ' · ' + p.detail : '')); });
      extra.forEach(function (e) { textBlock(e, CW - 6, 'normal', 9, C.ink, 13, M + 4); });
