        (Array.isArray(n[1]) ? n[1] : [n[1]]).forEach(function (t) { const l = lines(t, CW - 22, 'normal', 9); ensure(l.length * 12 + 3); fill(C.primary); doc.circle(M + 6, y + 6, 1.6, 'F'); font('normal', 9); ink(C.muted); doc.text(l, M + 16, y + 9); y += l.length * 12 + 3; });
