      fill(C.bg); doc.roundedRect(M, y, CW, th, 6, 6, 'F'); font('bold', 8.5); ink(C.primary); doc.text('TRAZABILIDAD', M + 14, y + 16); font('normal', 8.5); ink(C.ink); doc.text(tl, M + 14, y + 29); y += th + 10;
