  function loadPdfJs(cb) { if (window.pdfjsLib) return cb(); loadScript('pdf.min.js?v=20261119x', function () { window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'pdf.worker.min.js?v=20261119x'; cb(); }); }
